import { useCallback, useEffect, useRef, useSyncExternalStore } from "react";
import { ChunkedDictationSession } from "../core/chunked-dictation-session.js";
const IDLE_SNAPSHOT = {
  state: "idle",
  mode: "chunked",
  chunks: [],
  settledText: "",
  level: { levelDb: -100, thresholdDb: -55, voiced: false },
  durationMs: 0,
  speechMs: 0,
};
export function useChunkedDictation(options) {
  const optionsRef = useRef(options);
  optionsRef.current = options;
  const sessionRef = useRef(null);
  const unsubscribeRef = useRef(undefined);
  const snapshotRef = useRef(IDLE_SNAPSHOT);
  const listenersRef = useRef(new Set());
  const captureStartedRef = useRef(false);
  const startedSourceRef = useRef(undefined);
  const captureGenerationRef = useRef(0);
  const stoppingSessionRef = useRef(null);
  const emit = useCallback(() => {
    const session = sessionRef.current;
    snapshotRef.current = session ? session.getSnapshot() : IDLE_SNAPSHOT;
    for (const listener of listenersRef.current) listener();
  }, []);
  const subscribe = useCallback((listener) => {
    listenersRef.current.add(listener);
    return () => {
      listenersRef.current.delete(listener);
    };
  }, []);
  const getSnapshot = useCallback(() => snapshotRef.current, []);
  const snapshot = useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
  const attach = useCallback(
    (session) => {
      unsubscribeRef.current?.();
      sessionRef.current = session;
      unsubscribeRef.current = session.subscribe(emit);
      emit();
    },
    [emit]
  );
  const createSession = useCallback(() => {
    const { current } = optionsRef;
    const sessionOptions = {
      transport: current.transport,
      ...(current.languages ? { languages: current.languages } : {}),
      ...(current.maxDurationMs === undefined
        ? {}
        : { maxDurationMs: current.maxDurationMs }),
      ...(current.chunker ? { chunker: current.chunker } : {}),
    };
    const session = new ChunkedDictationSession(sessionOptions);
    attach(session);
    return session;
  }, [attach]);
  const ensureSession = useCallback(() => {
    const { current } = sessionRef;
    if (current && current !== stoppingSessionRef.current) {
      const { state } = current.getSnapshot();
      if (state !== "done" && state !== "cancelled" && state !== "error")
        return current;
    }
    return createSession();
  }, [createSession]);
  const startCapture = useCallback(async () => {
    const session = ensureSession();
    session.startCapture();
    const { frameSource } = optionsRef.current;
    if (!frameSource || captureStartedRef.current) return;
    const attempt = (captureGenerationRef.current += 1);
    captureStartedRef.current = true;
    startedSourceRef.current = frameSource;
    try {
      await frameSource.start((pcm) => session.pushAudio(pcm));
      if (captureGenerationRef.current !== attempt)
        await frameSource.stop().catch(() => undefined);
    } catch (error) {
      if (captureGenerationRef.current === attempt) {
        captureStartedRef.current = false;
        startedSourceRef.current = undefined;
      }
      throw error;
    }
  }, [ensureSession]);
  const stopStartedSource = useCallback(() => {
    captureGenerationRef.current += 1;
    const source = startedSourceRef.current;
    startedSourceRef.current = undefined;
    captureStartedRef.current = false;
    if (!source) return Promise.resolve();
    return source.stop();
  }, []);
  const connect = useCallback(() => {
    ensureSession().connect();
  }, [ensureSession]);
  const start = useCallback(async () => {
    await startCapture();
    connect();
  }, [connect, startCapture]);
  const stop = useCallback(
    async (input = {}) => {
      const session = sessionRef.current;
      if (session) stoppingSessionRef.current = session;
      await stopStartedSource().catch(() => undefined);
      return (session ?? ensureSession()).stop(input);
    },
    [ensureSession, stopStartedSource]
  );
  const cancel = useCallback(() => {
    stopStartedSource().catch(() => undefined);
    sessionRef.current?.cancel();
    emit();
  }, [emit, stopStartedSource]);
  useEffect(
    () => () => {
      unsubscribeRef.current?.();
      sessionRef.current?.cancel();
      captureGenerationRef.current += 1;
      const source = startedSourceRef.current;
      startedSourceRef.current = undefined;
      captureStartedRef.current = false;
      source?.stop().catch(() => undefined);
    },
    []
  );
  return { snapshot, startCapture, connect, start, stop, cancel };
}
